--
-- Table structure for table `asignaciones`
--

DROP TABLE IF EXISTS `asignaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `asignaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tecnico_id` bigint(20) unsigned NOT NULL,
  `asignado_por_id` bigint(20) unsigned NOT NULL,
  `lote_modelo_id` bigint(20) unsigned NOT NULL,
  `cantidad` smallint(5) unsigned NOT NULL COMMENT 'Cuántos equipos de ese modelo se asignan',
  `fecha_asignacion` date NOT NULL COMMENT 'Fecha en que se asignó el equipo',
  `fecha_entrega` date DEFAULT NULL COMMENT 'Fecha en que el técnico entregó el equipo terminado',
  `estatus` enum('PENDIENTE','EN_PROCESO','ENTREGADO','VALIDADO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE',
  `notas` text DEFAULT NULL COMMENT 'Instrucciones especiales o comentarios',
  `notas_entrega` text DEFAULT NULL COMMENT 'Notas del técnico al entregar',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `asignaciones_asignado_por_id_foreign` (`asignado_por_id`),
  KEY `asignaciones_tecnico_id_index` (`tecnico_id`),
  KEY `asignaciones_estatus_index` (`estatus`),
  KEY `asignaciones_fecha_asignacion_index` (`fecha_asignacion`),
  KEY `asignaciones_lote_modelo_id_index` (`lote_modelo_id`),
  CONSTRAINT `asignaciones_asignado_por_id_foreign` FOREIGN KEY (`asignado_por_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `asignaciones_lote_modelo_id_foreign` FOREIGN KEY (`lote_modelo_id`) REFERENCES `lote_modelos_recibidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `asignaciones_tecnico_id_foreign` FOREIGN KEY (`tecnico_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

