/*!50003 CREATE*/ /*!50017 DEFINER=`tcbt`@`localhost`*/ /*!50003 TRIGGER trg_equipo_gpus_ai
AFTER INSERT ON equipo_gpus
FOR EACH ROW
BEGIN
    UPDATE equipos
    SET
        tiene_grafica_integrada = EXISTS (
            SELECT 1 FROM equipo_gpus
            WHERE equipo_id = NEW.equipo_id
              AND tipo = 'INTEGRADA'
              AND activo = 1
        ),
        tiene_grafica_dedicada = EXISTS (
            SELECT 1 FROM equipo_gpus
            WHERE equipo_id = NEW.equipo_id
              AND tipo = 'DEDICADA'
              AND activo = 1
        )
    WHERE id = NEW.equipo_id;
END */;;
DELIMITER ;
