CREATE TABLE `equipo_monitores` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint(20) unsigned NOT NULL,
  `origen_pantalla` enum('INTEGRADA','EXTERNA') NOT NULL,
  `incluido` tinyint(1) NOT NULL DEFAULT 1,
  `pulgadas` varchar(20) DEFAULT NULL,
  `resolucion` varchar(30) DEFAULT NULL,
  `tipo_panel` varchar(30) DEFAULT NULL,
  `es_touch` tinyint(1) DEFAULT NULL,
  `in_hdmi` tinyint(3) unsigned DEFAULT NULL,
  `in_mini_hdmi` tinyint(3) unsigned DEFAULT NULL,
  `in_vga` tinyint(3) unsigned DEFAULT NULL,
  `in_dvi` tinyint(3) unsigned DEFAULT NULL,
  `in_displayport` tinyint(3) unsigned DEFAULT NULL,
  `in_mini_displayport` tinyint(3) unsigned DEFAULT NULL,
  `in_usb_2` tinyint(3) unsigned DEFAULT NULL,
  `in_usb_3` tinyint(3) unsigned DEFAULT NULL,
  `in_usb_31` tinyint(3) unsigned DEFAULT NULL,
  `in_usb_32` tinyint(3) unsigned DEFAULT NULL,
  `in_usb_c` tinyint(3) unsigned DEFAULT NULL,
  `detalles_esteticos_checks` text DEFAULT NULL,
  `detalles_esteticos_otro` text DEFAULT NULL,
  `detalles_funcionamiento_checks` text DEFAULT NULL,
  `detalles_funcionamiento_otro` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `equipo_monitores_equipo_id_unique` (`equipo_id`),
  KEY `equipo_monitores_origen_pantalla_index` (`origen_pantalla`),
  CONSTRAINT `equipo_monitores_equipo_id_foreign` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1488 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
