CREATE TABLE `inventario_piezas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `catalogo_pieza_id` bigint(20) unsigned NOT NULL,
  `numero_serie` varchar(100) DEFAULT NULL COMMENT 'Número de serie si aplica (SSD, RAM, etc.)',
  `origen` enum('COMPRA','DESHUESO') NOT NULL DEFAULT 'COMPRA' COMMENT 'De dónde vino la pieza',
  `compra_item_id` bigint(20) unsigned DEFAULT NULL,
  `equipo_origen_id` bigint(20) unsigned DEFAULT NULL,
  `equipo_destino_id` bigint(20) unsigned DEFAULT NULL,
  `almacen_id` bigint(20) unsigned NOT NULL DEFAULT 7,
  `costo` decimal(10,2) DEFAULT NULL COMMENT 'Costo de la pieza (registrado por gerente al comprar)',
  `registrado_por_id` bigint(20) unsigned DEFAULT NULL,
  `estatus` enum('DISPONIBLE','AGOTADA','DADA_DE_BAJA') NOT NULL DEFAULT 'DISPONIBLE',
  `fecha_ingreso` date DEFAULT NULL,
  `notas` text DEFAULT NULL,
  `cantidad_inicial` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Cuántas unidades entraron en esta entrada',
  `cantidad_disponible` int(10) unsigned NOT NULL DEFAULT 1 COMMENT 'Cuántas unidades están disponibles para asignar',
  `cantidad_reservada` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Cuántas unidades están reservadas para solicitudes activas',
  `cantidad_usada` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Cuántas unidades ya fueron instaladas exitosamente',
  `cantidad_baja` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Cuántas unidades fallaron o fueron dadas de baja',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inventario_piezas_equipo_origen_id_foreign` (`equipo_origen_id`),
  KEY `inventario_piezas_registrado_por_id_foreign` (`registrado_por_id`),
  KEY `inventario_piezas_catalogo_pieza_id_index` (`catalogo_pieza_id`),
  KEY `inventario_piezas_estatus_index` (`estatus`),
  KEY `inventario_piezas_almacen_id_index` (`almacen_id`),
  KEY `inventario_piezas_equipo_destino_id_foreign` (`equipo_destino_id`),
  KEY `inventario_piezas_compra_item_id_foreign` (`compra_item_id`),
  CONSTRAINT `inventario_piezas_almacen_id_foreign` FOREIGN KEY (`almacen_id`) REFERENCES `almacenes` (`id`),
  CONSTRAINT `inventario_piezas_catalogo_pieza_id_foreign` FOREIGN KEY (`catalogo_pieza_id`) REFERENCES `catalogo_piezas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inventario_piezas_compra_item_id_foreign` FOREIGN KEY (`compra_item_id`) REFERENCES `compras_inventario_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventario_piezas_equipo_destino_id_foreign` FOREIGN KEY (`equipo_destino_id`) REFERENCES `equipos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventario_piezas_equipo_origen_id_foreign` FOREIGN KEY (`equipo_origen_id`) REFERENCES `equipos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventario_piezas_registrado_por_id_foreign` FOREIGN KEY (`registrado_por_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
