-- Table structure for table `lote_modelos_recibidos`
--

DROP TABLE IF EXISTS `lote_modelos_recibidos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lote_modelos_recibidos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `lote_id` bigint(20) unsigned NOT NULL,
  `marca` varchar(100) NOT NULL COMMENT 'Ej: Dell',
  `modelo` varchar(255) NOT NULL COMMENT 'Ej: Precision 5770',
  `cantidad_recibida` int(10) unsigned NOT NULL COMMENT 'Ej: 40',
  `valor_unitario` decimal(10,2) DEFAULT NULL COMMENT 'Precio unitario por equipo de este modelo en el lote',
  `clasificacion_puntos_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `lote_id` (`lote_id`),
  KEY `lote_modelos_recibidos_clasificacion_puntos_id_foreign` (`clasificacion_puntos_id`),
  CONSTRAINT `lote_modelos_recibidos_clasificacion_puntos_id_foreign` FOREIGN KEY (`clasificacion_puntos_id`) REFERENCES `clasificaciones_puntos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `lote_modelos_recibidos_ibfk_1` FOREIGN KEY (`lote_id`) REFERENCES `lotes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

