DROP TABLE IF EXISTS `puntos_tecnicos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `puntos_tecnicos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tecnico_id` bigint(20) unsigned NOT NULL,
  `asignacion_equipo_id` bigint(20) unsigned NOT NULL,
  `clasificacion_puntos_id` bigint(20) unsigned DEFAULT NULL,
  `puntos_base` decimal(5,2) NOT NULL COMMENT 'Puntos base de la clasificación (copiado al momento)',
  `porcentaje_aplicado` decimal(5,2) NOT NULL DEFAULT 100.00 COMMENT '% aplicado según camino: 100=completo, 40=inició pieza, 60=terminó pieza, 30=garantía',
  `puntos_final` decimal(5,2) NOT NULL COMMENT 'Puntos reales = puntos_base * (porcentaje_aplicado / 100) + ajuste_manual',
  `ajuste_manual` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Ajuste del gerente, puede ser positivo o negativo',
  `ajustado_por_id` bigint(20) unsigned DEFAULT NULL,
  `motivo_ajuste` text DEFAULT NULL,
  `rol_en_equipo` enum('COMPLETO','INICIO_PIEZA','TERMINO_PIEZA','GARANTIA') NOT NULL COMMENT 'Qué rol tuvo el técnico en este equipo',
  `periodo` char(7) NOT NULL COMMENT 'Año-Mes en formato YYYY-MM, ej: 2026-03',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `puntos_tecnicos_asignacion_equipo_id_foreign` (`asignacion_equipo_id`),
  KEY `puntos_tecnicos_clasificacion_puntos_id_foreign` (`clasificacion_puntos_id`),
  KEY `puntos_tecnicos_ajustado_por_id_foreign` (`ajustado_por_id`),
  KEY `puntos_tecnicos_tecnico_id_index` (`tecnico_id`),
  KEY `puntos_tecnicos_periodo_index` (`periodo`),
  KEY `puntos_tecnicos_tecnico_id_periodo_index` (`tecnico_id`,`periodo`),
  KEY `puntos_tecnicos_rol_en_equipo_index` (`rol_en_equipo`),
  CONSTRAINT `puntos_tecnicos_ajustado_por_id_foreign` FOREIGN KEY (`ajustado_por_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `puntos_tecnicos_asignacion_equipo_id_foreign` FOREIGN KEY (`asignacion_equipo_id`) REFERENCES `asignacion_equipos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `puntos_tecnicos_clasificacion_puntos_id_foreign` FOREIGN KEY (`clasificacion_puntos_id`) REFERENCES `clasificaciones_puntos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `puntos_tecnicos_tecnico_id_foreign` FOREIGN KEY (`tecnico_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=392 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
