DROP TABLE IF EXISTS `solicitudes_piezas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `solicitudes_piezas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `asignacion_equipo_id` bigint(20) unsigned NOT NULL,
  `equipo_id` bigint(20) unsigned DEFAULT NULL,
  `solicitado_por_id` bigint(20) unsigned NOT NULL,
  `catalogo_pieza_id` bigint(20) unsigned DEFAULT NULL,
  `descripcion_libre` varchar(255) DEFAULT NULL COMMENT 'Descripción si la pieza no está en catálogo',
  `cantidad` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'Cantidad de unidades de esta pieza que necesita el técnico',
  `estatus` enum('PENDIENTE','SURTIDA_INVENTARIO','PENDIENTE_COMPRA','COMPRADA','CANCELADA','CONFIRMADA') NOT NULL DEFAULT 'PENDIENTE',
  `inventario_pieza_id` bigint(20) unsigned DEFAULT NULL,
  `respondida_por_id` bigint(20) unsigned DEFAULT NULL,
  `reasignado_a_id` bigint(20) unsigned DEFAULT NULL,
  `reasignada_en` timestamp NULL DEFAULT NULL,
  `iniciada_instalacion_en` timestamp NULL DEFAULT NULL,
  `respondida_en` timestamp NULL DEFAULT NULL,
  `notas_respuesta` text DEFAULT NULL,
  `puntos_override` decimal(8,2) DEFAULT NULL COMMENT 'Valor en puntos definido por el gerente al asignar la pieza. Si es null, se usa el puntos_base del equipo.',
  `instalada` tinyint(1) NOT NULL DEFAULT 0,
  `funciono` tinyint(1) DEFAULT NULL,
  `confirmada_en` timestamp NULL DEFAULT NULL,
  `notas_confirmacion` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `solicitudes_piezas_catalogo_pieza_id_foreign` (`catalogo_pieza_id`),
  KEY `solicitudes_piezas_inventario_pieza_id_foreign` (`inventario_pieza_id`),
  KEY `solicitudes_piezas_respondida_por_id_foreign` (`respondida_por_id`),
  KEY `solicitudes_piezas_asignacion_equipo_id_index` (`asignacion_equipo_id`),
  KEY `solicitudes_piezas_estatus_index` (`estatus`),
  KEY `solicitudes_piezas_solicitado_por_id_index` (`solicitado_por_id`),
  KEY `solicitudes_piezas_equipo_id_foreign` (`equipo_id`),
  KEY `solicitudes_piezas_reasignado_a_id_foreign` (`reasignado_a_id`),
  CONSTRAINT `solicitudes_piezas_asignacion_equipo_id_foreign` FOREIGN KEY (`asignacion_equipo_id`) REFERENCES `asignacion_equipos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `solicitudes_piezas_catalogo_pieza_id_foreign` FOREIGN KEY (`catalogo_pieza_id`) REFERENCES `catalogo_piezas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `solicitudes_piezas_equipo_id_foreign` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `solicitudes_piezas_inventario_pieza_id_foreign` FOREIGN KEY (`inventario_pieza_id`) REFERENCES `inventario_piezas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `solicitudes_piezas_reasignado_a_id_foreign` FOREIGN KEY (`reasignado_a_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `solicitudes_piezas_respondida_por_id_foreign` FOREIGN KEY (`respondida_por_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `solicitudes_piezas_solicitado_por_id_foreign` FOREIGN KEY (`solicitado_por_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
